# owner: platform
from typing import List, Iterable
from hourglass.parsing import format_clock, format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def _check_inside(worked: Iterable[Span], opening: Span) -> None:
    for span in worked:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(f"{format_span(span)} is outside opening hours")


def _label(begin: int, finish: int) -> str:
    return f"gap {format_clock(begin)}-{format_clock(finish)} ({finish - begin} min)"


# ---
def find_gaps(worked: Iterable[Span], opening: Span) -> List[str]:
    _check_inside(worked, opening)
    edges = [opening.start]
    for span in merge_spans(worked):
        edges += [span.start, span.end]
    edges.append(opening.end)
    pairs = zip(edges[0::2], edges[1::2])
    return [_label(begin, finish) for begin, finish in pairs if begin < finish]
